import * as React from 'react';
import * as S from '@primasoftllc/design-system';

export function Example(){
const [done,setDone]=React.useState(false);
return <div style={{display:'grid',gap:16}}><S.DsProgressBar label="Подготовка отчёта" value={done?100:undefined} valueText={done?'Готово':'Подготавливаем данные'} tone={done?'success':'primary'}/><S.DsButton tone="secondary" onClick={()=>setDone(current=>!current)}>{done?'Повторить пример':'Завершить подготовку'}</S.DsButton><p role="status" style={{margin:0}}>{done?'Данные готовы.':''}</p></div>;
}

